mapper.select:
SELECT * FROM torn_stock_signal_event event
WHERE round_time = #{roundTime}
  AND deleted = 0

mapper.update:
UPDATE torn_stock_signal_event SET later_mfe = source.later_mfe, later_mae = source.later_mae, resolved_at = source.resolved_at, observation_result = source.observation_result, observation_data_incomplete = source.observation_data_incomplete, update_time = CURRENT_TIMESTAMP FROM (VALUES
(CAST(#{event.id} AS BIGINT), CAST(#{event.laterMfe} AS NUMERIC(18,10)), CAST(#{event.laterMae} AS NUMERIC(18,10)), CAST(#{event.resolvedAt} AS TIMESTAMP), CAST(#{event.observationResult} AS VARCHAR(64)), CAST(#{event.observationDataIncomplete} AS BOOLEAN))
) AS source(id, later_mfe, later_mae, resolved_at, observation_result, observation_data_incomplete) WHERE torn_stock_signal_event.id = source.id AND torn_stock_signal_event.resolved_at IS NULL
